  'ORGANIZATION' = 'ORGANIZATION',
  'CAMPAIGN' = 'CAMPAIGN',
  'PUBLIC_COMPANY_FILE' = 'PUBLIC_COMPANY_FILE',
  'PUBLIC_PEOPLE_FILE' = 'PUBLIC_PEOPLE_FILE',
  'USER' = 'USER',
  'CLIENT' = 'CLIENT',
  'SMARTLEAD_OPPORTUNITY' = 'SMARTLEAD_OPPORTUNITY',
  'PERSONA' = 'PERSONA',
  'SEQUENCE_CAMPAIGN' = 'SEQUENCE_CAMPAIGN',
  'SEQUENCE_CAMPAIGN_TEMPLATE' = 'SEQUENCE_CAMPAIGN_TEMPLATE',
  'SCRAPE' = 'SCRAPE',
  'STORE_LEADS_DOMAIN_EXPORT' = 'STORE_LEADS_DOMAIN_EXPORT',
  'REGISTERED_WEBHOOK' = 'REGISTERED_WEBHOOK',
  'JOB_STATUS' = 'JOB_STATUS',
  'GATE_ENRICHER' = 'GATE_ENRICHER',
  'DECISION_MAKER' = 'DECISION_MAKER',
}
