import { Module } from '@nestjs/common';
import { DatastoreService } from './datastore.service';
import { FileSystemDataStoreEntity } from './entites/fileSystemDataStore.entity';
import { ModuleRef } from '@nestjs/core';
import { RedisDataStoreEntity } from './entites/redisDataStore.entity';
import { MongoDataStoreEntity } from './entites/mongoDataStoreEntity.entity';

@Module({
  providers: [
    DatastoreService,
    FileSystemDataStoreEntity,
    RedisDataStoreEntity,
    MongoDataStoreEntity,
  ],
  exports: [DatastoreService],
})
export class DatastoreModule {
  fileSystemDataStoreEntity: FileSystemDataStoreEntity;
  redisDataStoreEntity: FileSystemDataStoreEntity;
  mongoDataStoreEntity: MongoDataStoreEntity;
  constructor(private moduleRef: ModuleRef) {}
  async onModuleInit() {
    if (process.env.DATASTORE.toUpperCase() === 'FILESYSTEM') {
      this.fileSystemDataStoreEntity = this.moduleRef.get(
        FileSystemDataStoreEntity,
        { strict: false },
      );
    }
    if (process.env.DATASTORE.toUpperCase() === 'REDIS') {
      this.redisDataStoreEntity = this.moduleRef.get(RedisDataStoreEntity, {
        strict: false,
      });
    }
    if (process.env.DATASTORE.toUpperCase() === 'MONGO') {
      this.mongoDataStoreEntity = this.moduleRef.get(MongoDataStoreEntity, {
        strict: false,
      });
    }
    await DatastoreService.init([
      this.fileSystemDataStoreEntity,
      this.redisDataStoreEntity,
      this.mongoDataStoreEntity,
    ]);
  }
}

