  async getCampaignData(
    campaignId: string | number,
  ): Promise<SmartleadCampaignDto> {
    this.logger.log(
      `Getting smartlead campaign data for campaign: ${campaignId}`,
    );
    const inputCampaignId = parseInt(campaignId.toString());
    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
    const campaignRes = await fetch(
      `https://server.smartlead.ai/api/v1/campaigns/${inputCampaignId}?api_key=${apiKey}`,
    );
    if (campaignRes.status === 404) {
      this.logger.error(`Campaign not found: ${campaignId}`);
      throw new NotFoundException('Campaign not found');
    }
    return await campaignRes.json();
  }

  async getSmartleadClientId(orgId: string): Promise<string> {
    return await this.usersService.findSmartleadClientIdForOrg(orgId);
  }

  async createNewCampaign(
    campaignId: string,
    clientId: string,
  ): Promise<SmartleadCampaignDto> {
    /**
     * 
     * curl <https://server.smartlead.ai/api/v1/campaigns/create?api_key=${API_KEY}>
--data { "name": "Test email campaign", "client_id": 22 // leave null if no client }
    */
    this.logger.log(
      `Creating new campaign: ${campaignId} for client: ${clientId}`,
    );
    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
    const body = {
      name: campaignId,
      client_id: parseInt(clientId),
    };
    this.logger.log(`Body for create new campaign: ${body}`);
    const campaignRes = await fetch(
      `https://server.smartlead.ai/api/v1/campaigns/create?api_key=${apiKey}`,
      {
        method: 'POST',
        body: JSON.stringify(body),
        headers: {
          'Content-Type': 'application/json',
        },
      },
    );
    return await campaignRes.json();
  }
  async createSmartleadClientId(orgId: string): Promise<{
    clientId: string;
    password: string;
    orgId: string;
    email: string;
  }> {
    this.logger.log(
      `createSmartleadClientId Creating smartlead client id for orgId: ${orgId}`,
    );
    // Create a new smartlead client id
    const passwordLength = 16;
    const password = generatePassword(passwordLength);
    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
    const res = await fetch(
      `https://server.smartlead.ai/api/v1/client/save?api_key=${apiKey}`,
      {
        method: 'POST',
        body: JSON.stringify({
          name: orgId,
          email: `${orgId}@trychamp.co`,
          permission: ['reply_master_inbox'],
          logo: orgId,
          password,
        }),
        headers: {
          'Content-Type': 'application/json',
        },
      },
    );
    if (!res.ok) {
      this.logger.error(`Failed to create smartlead client id: ${res.status}`);
      try {
        const resJson = await res.json();
        this.logger.error(
          `ERROR JSON Response: ${JSON.stringify(resJson ? resJson : {})}`,
        );
      } catch (error) {
        this.logger.error(
          `Failed to parse smartlead client creation error response: ${error}`,
        );
        try {
          const resText = await res.text();
          this.logger.error(`Text Response: ${resText}`);
        } catch (error) {
          this.logger.error(`Failed to parse error for text: ${error}`);
        }
      }

      throw new InternalServerErrorException(
        'Failed to create smartlead client id',
      );
    }
    const resJson = await res.json();
    this.logger.log(
      `createSmartleadClientId Response: ${JSON.stringify(resJson ? resJson : {})}`,
    );
    return {
      clientId: resJson.clientId,
      password: resJson.password,
      orgId,
      email: `${orgId}@trychamp.co`,
    };
  }
  async propagateSmartleadClientsToRetool({
    email,
    password,
    clientId,
    userIds,
  }: {
    email: string;
    password: string;
    clientId: string;
    userIds: string[];
  }) {
    // Call retool workflow, pass parameters, log errors and intial arguments, response etc...
    /*
    curl -X POST --url "https://api.retool.com/v1/workflows/04a90e87-91d0-42c9-ad0b-8b335a050885/startTrigger" -H 'Content-Type: application/json' -H 'X-Workflow-Api-Key: retool_wk_fe506347782e4285905c42c0a5baf8c7'
    */
    const retoolWorkflowUrl = `https://api.retool.com/v1/workflows/04a90e87-91d0-42c9-ad0b-8b335a050885/startTrigger`;
    try {
      await Promise.all(
        userIds.map(async (userId) => {
          const retoolWorkflowResponse = await fetch(retoolWorkflowUrl, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'X-Workflow-Api-Key':
                'retool_wk_fe506347782e4285905c42c0a5baf8c7',
            },
            body: JSON.stringify({ email, password, clientId, userId }),
          });
          if (!retoolWorkflowResponse.ok) {
            this.logger.error(
              `Failed to propagate smartlead clients to retool: ${retoolWorkflowResponse.status}`,
            );
            try {
              const retoolWorkflowResponseJson =
                await retoolWorkflowResponse.json();
              this.logger.error(
                `Retool workflow response JSON: ${JSON.stringify(
                  retoolWorkflowResponseJson ? retoolWorkflowResponseJson : {},
                )}`,
              );
            } catch (e) {
              this.logger.error(`Error parsing retool workflow response: ${e}`);
              try {
                const retoolWorkflowResponseText =
                  await retoolWorkflowResponse.text();
                this.logger.error(
                  `Retool workflow response text: ${retoolWorkflowResponseText}`,
                );
              } catch (e) {
                this.logger.error(
                  `Error parsing retool workflow response text: ${e}`,
                );
              }
              throw new InternalServerErrorException(
                `Failed to propagate smartlead clients to retool: ${retoolWorkflowResponse.status}`,
              );
            }
            const retoolWorkflowResponseJson =
              await retoolWorkflowResponse.json();
            this.logger.log(
              `Retool workflow response JSON: ${JSON.stringify(
                retoolWorkflowResponseJson ? retoolWorkflowResponseJson : {},
              )}`,
            );
            return retoolWorkflowResponseJson;
          }
          this.logger.log(
            `Successfully propagated smartlead clients to retool`,
          );
          const retoolWorkflowResponseJson =
            await retoolWorkflowResponse.json();
          this.logger.log(
            `Retool workflow response JSON: ${JSON.stringify(
              retoolWorkflowResponseJson ? retoolWorkflowResponseJson : {},
            )}`,
          );
          return {
            message: 'Success',
          };
        }),
      );
    } catch (e) {
      this.logger.error(`Error propagating smartlead clients to retool: ${e}`);
    }
  }

  async sequenceToSmartlead({
    sequence,
    campaignId,
    orgId,
    smartleadCampaignId,
    retoolId,
  }: {
    sequence: SequenceWriterEnricherOutputDto[];
    campaignId: string;
    orgId: string;
    smartleadCampaignId?: string;
    clickupTaskId: string;
    retoolId: string;
  }) {
    // Given the clientId, assume the campaign exists
    // Get the campaign data
    this.logger.log(`Getting campaign data for campaign: ${campaignId}`);
    let campaignData: SmartleadCampaignDto;
    let smartleadClientId = await this.getSmartleadClientId(orgId);
    if (!smartleadClientId) {
      this.logger.log(
        `Smartlead client ID not found for orgId: ${orgId} creating one`,
      );
      const { clientId, password, email } =
        await this.createSmartleadClientId(orgId);
      smartleadClientId = clientId;
      this.logger.log(
        `Smartlead client ID created for orgId: ${orgId} smartLeadClientId: ${smartleadClientId}`,
      );
      // Get all userIds for orgId
      const users = await this.usersService.listClients();
      const userIds = users.filter((u) => u.org === orgId).map((u) => u.userId);
      this.logger.log(`User IDs for orgId: ${orgId}`);
      this.logger.log(`User IDs: ${JSON.stringify(userIds ? userIds : [])}`);
      if (!userIds || userIds.length === 0) {
        this.logger.error(
          `No user IDs found for orgId: ${orgId}, skipping propagation`,
        );
      } else {
        await this.propagateSmartleadClientsToRetool({
          email,
          password,
          clientId,
          userIds,
        });
      }

      try {
        this.logger.log(`Getting clients for orgId: ${orgId}`);
        const clients = await this.usersService.findClientsForOrg(orgId);
        // Filter for clients who don't have a smartleadId
        const clientsWithoutSmartleadId = clients.filter((c) => !c.smartleadId);
        this.logger.log(
          `Clients without smartleadId: ${JSON.stringify(
            clientsWithoutSmartleadId ? clientsWithoutSmartleadId : [],
          )}`,
        );
        await Promise.all(
          clientsWithoutSmartleadId.map((c) =>
            this.usersService.addSmartleadToClient(
              c.clientId,
              smartleadClientId,
            ),
          ),
        );
      } catch (e) {
        this.logger.error(
          `Error adding smartlead to clients: ${JSON.stringify(e)}`,
        );
      }
    }
    try {
      if (smartleadCampaignId) {
        this.logger.log(
          `Getting smartlead campaign data for campaign: ${smartleadCampaignId}`,
        );
        campaignData = await this.getCampaignData(smartleadCampaignId);
      } else {
        const res = await this.createNewCampaign(campaignId, smartleadClientId);
        this.logger.log(
          `Created new campaign this.createNewCampaign: ${campaignId}`,
        );
        this.logger.log(
          `Getting campaign data for campaign: ${JSON.stringify(res ? res : {})}`,
        );
        campaignData = await this.getCampaignData(res?.id);
        //
      }
    } catch (e) {
      if (e instanceof NotFoundException) {
        this.logger.warn(`Campaign not found: ${campaignId}`);
        // Create a new campaign
        const res = await this.createNewCampaign(campaignId, smartleadClientId);
        this.logger.log(
          `Created new campaign this.createNewCampaign: ${campaignId}`,
        );

        campaignData = await this.getCampaignData(res?.id);
        //
      } else {
        this.logger.error(
          `Error getting campaign data for campaign: ${campaignId}`,
        );
        throw e;
      }
    }
    this.logger.log(`Got campaign data for campaign: ${campaignId}`);
    const storedSequence =
      await this.orchestratorService.getSavedSequenceDocument(
        campaignId,
        orgId,
      );
    this.logger.log(
      `getSavedSequenceDocument: ${JSON.stringify(storedSequence ? storedSequence : {})}`,
    );
    // We will for now assume that the smartlead clientId is going to be there, in cases where it isn't in the future we should assume that this is the first campaign, andd we create one where we add it to their org for all users. But for now we will ignore this.
    this.logger.log(
      `Creating new SmartleadCampaign with campaignData: ${JSON.stringify(
        campaignData ? campaignData : {},
      )}`,
    );
    const campaign = new SmartleadCampaign(campaignData);
    await campaign.updateGeneralSettings(campaignId);
    const leads: SmartleadLeadDto[] = sequence
      .map((s) => {
        if (s?.isValid) {
          return {
            email: s.email,
            first_name: s.firstName,
            last_name: s.lastName,
            company_name: s.companyName,
            website: s.companyWebsite,
            location: s.city,
            linkedin_profile: s.companyLinkedinUrl,
            company_url: s.companyWebsite,
            custom_fields: {
              State: s.state,
              Country: s.country,
              Title: s.title,
              Company_Linkedin_Url: s.companyLinkedinUrl,
              Template_1_Output: s['Template 1 Output'],
              Template_2_Output: s['Template 2 Output'],
              Template_3_Output: s['Template 3 Output'],
              Template_4_Output: s['Template 4 Output'],
              Company_Short_Name: s.companyShortName,
            },
          };
        } else {
          return null;
        }
      })
      .filter((e) => e !== null);
    const { successfulLeadsCount } = await campaign.addLeads(leads);
    await campaign.addSequence(storedSequence);
    this.logger.log(`Added sequence to campaign: ${campaignId}`);

    this.logger.log(`campaign.addLeads: ${campaignId}`);
    await campaign.pauseCampaign();
    this.logger.log(`campaign.pauseCampaign: ${campaignId}`);
    await campaign.exportCampaignToDownstream({
      retoolId: retoolId,
    });
    await this.clickupService.createDeliveryOpsTask({
      taskName: `Update Lead Credits for ${orgId}`,
      dueDate: new Date(Date.now() + 1000 * 60 * 60 * 24).getTime(),
      description: `OrgId: ${orgId} just launched a new campaign: ${campaignId}. Inside of smartlead we loaded the following leads: ${successfulLeadsCount}`,
    });
    this.logger.log(`campaign.exportCampaignToDownstream: ${campaignId}`);
    // Start the campaign
    // await campaign.startCampaign();
    // this.logger.log(`campaign.startCampaign: ${campaignId}`);
    return {
      message: 'Campaign created successfully',
      smartleadCampaignId: campaignData?.id,
      smartleadCampaignName: campaignId,
    };
  }
}

