import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { DatastoreService } from '../../datastore/datastore.service';
import { documentType } from '../../datastore/entites/documentType';
import { StoreDataDto } from '../../datastore/dto/store.dto';
import { Persona } from './Persona';

@Injectable()
export class PersonaEntity {
  private readonly logger = new Logger(PersonaEntity.name);
  constructor(private readonly datastoreService: DatastoreService) {}

  async create(persona: Persona): Promise<Persona> {
    let createdAt = new Date().toISOString();
    if (persona?.id) {
      try {
        const existingPersona = await this.read(persona.id);
        createdAt = existingPersona.createdAt
          ? existingPersona.createdAt
          : new Date().toISOString();
      } catch (error) {
        this.logger.error(error);
        createdAt = new Date().toISOString();
      }
    }
    const entity = new Persona(persona);
    entity.createdAt = createdAt;
    entity.updatedAt = new Date().toISOString();
    const storeData: StoreDataDto = {
      data: entity,
      context: {
        uniqueId: entity.id,
        documentType: documentType.PERSONA,
      },
    };
    await this.datastoreService.store(storeData);
    return entity;
  }

  async read(id: string): Promise<Persona> {
    const res = await this.datastoreService.getByField({
      fieldKey: 'data.id',
      fieldValue: id,
      documentType: documentType.PERSONA,
    });
    if (!res?.data || res?.data.length === 0) {
      throw new NotFoundException('Persona not found');
    }
    const persona = res.data[0];
    return new Persona(persona);
  }

  async readByStrategyId(strategyId: string): Promise<Persona> {
    const res = await this.datastoreService.getByField({
      fieldKey: 'data.strategyId',
      fieldValue: strategyId,
      documentType: documentType.PERSONA,
    });
    if (!res?.data || res?.data.length === 0) {
      throw new NotFoundException('Persona not found');
    }
    const persona = res.data[0];
    return new Persona(persona);
  }
  static async readAll(
    orgId: string,
    datastoreService: DatastoreService,
  ): Promise<Persona[]> {
    const res = await datastoreService.getByField({
      fieldKey: 'data.orgId',
      fieldValue: orgId,
      documentType: documentType.PERSONA,
    });
    if (!res?.data || res?.data.length === 0) {
      return [];
    }
    return res.data.map((item) => new Persona(item.data));
  }
  static async readAllDocs(datastoreService: DatastoreService) {
    const res = await datastoreService.getByField({
      fieldKey: 'data.id',
      fieldValue: { $exists: true },
      documentType: documentType.PERSONA,
    });
    if (!res?.data || res?.data.length === 0) {
      return [];
    }
    return res.data.map((item) => new Persona(item));
  }
  async delete(id: string) {
    await this.datastoreService.remove({
      id,
      documentType: documentType.PERSONA,
    });
    return {
      message: 'Persona deleted successfully',
    };
  }
}
