    this.logger.log(`Getting campaigns for org ${orgId}`);
    return this.campaignEntity.getCampaignsForOrg(orgId);
  }

  public async createCampaign(createCampaignDto: CreateCampaignDto) {
    try {
      await this.getCampaign({
        campaignId: createCampaignDto.campaignId,
        orgId: createCampaignDto.orgId,
      });
      this.logger.log(
        `Campaign ${createCampaignDto.campaignId} already exists`,
      );
      return;
