export class Campaign {
  private readonly logger = new Logger(Campaign.name);
  orgId: string;
  campaignId: string;

  constructor(partial: Partial<Campaign>) {
    Object.assign(this, partial);
  }
  async get(datastoreService: DatastoreService): Promise<Campaign> {
    this.logger.log(
      `Getting campaign ${this.campaignId} for org ${this.orgId}`,
    );
    const res = await datastoreService.getByField({
      fieldValue: this.campaignId,
      fieldKey: 'data.campaignId',
      documentType: documentType.CAMPAIGN,
    });
    if (!res?.data?.length) {
      throw new NotFoundException(`Campaign ${this.campaignId} not found`);
    }
    if (res?.data?.[0]?.orgId !== this.orgId) {
      throw new NotFoundException(`Campaign ${this.campaignId} not found `);
    }

    return res.data[0];
  }
  static async getAll(
    datastoreService: DatastoreService,
    { orgId }: { orgId: string },
  ): Promise<Campaign[]> {
    const res = await datastoreService.getByField({
      fieldValue: orgId,
      fieldKey: 'data.orgId',
      documentType: documentType.CAMPAIGN,
    });
    if (!res?.data?.length) {
      return [];
    }
    return res.data.map((c) => new Campaign(c));
  }
  async delete(datastoreService: DatastoreService): Promise<void> {
    await this.get(datastoreService);
    this.logger.log(`Deleting campaign ${this.campaignId}`);
    await datastoreService.remove({
      id: this.campaignId,
      documentType: documentType.CAMPAIGN,
    });
    this.logger.log(`Deleted campaign ${this.campaignId}`);
    return;
  }
  async create(datastoreService: DatastoreService): Promise<void> {
    this.logger.log(`Creating campaign ${this.campaignId}`);
    await datastoreService.store(
      new StoreDataDto({
        data: {
          id: this.campaignId,
          campaignId: this.campaignId,
          orgId: this.orgId,
        },
        context: {
          uniqueId: this.campaignId,
          documentType: documentType.CAMPAIGN,
        },
      }),
    );
    this.logger.log(`Created campaign ${this.campaignId}`);
    return;
  }
}
@Injectable()
export class CampaignEntity {
  private logger = new Logger(CampaignEntity.name);
  constructor(readonly datastoreService: DatastoreService) {}
  async getCampaignsForOrg(orgId: string): Promise<string[]> {
    const dbCampaigns = await this.getAll({ orgId });
    if (!staticCampaignMap[orgId]) {
      return dbCampaigns;
    }
    const campaigns = staticCampaignMap[orgId];
    // Should deduplicate campaigns
    return [...campaigns, ...dbCampaigns].filter(
      (c, index, self) => c === self.find((t) => t === c),
    );
  }

  public async get({
    campaignId,
    orgId,
  }: {
    campaignId: string;
    orgId: string;
  }): Promise<string> {
    if (
      staticCampaignMap[orgId] &&
      staticCampaignMap[orgId]?.includes(campaignId)
    ) {
      return campaignId;
    }
    const campaign = new Campaign({ campaignId, orgId });
    return (await campaign.get(this.datastoreService)).campaignId;
  }

  public async getAll({ orgId }: { orgId: string }): Promise<string[]> {
    const dbCampaigns = await Campaign.getAll(this.datastoreService, {
      orgId,
    });
    if (!staticCampaignMap[orgId]) {
      return dbCampaigns.map((c) => c.campaignId);
    }
    const mappedCampaigns = staticCampaignMap[orgId].map(
      (c) =>
        new Campaign({
          campaignId: c,
          orgId,
        }),
    );
    return [...mappedCampaigns, ...dbCampaigns].map((c) => c.campaignId);
  }

  public async delete({
    campaignId,
    orgId,
  }: {
    campaignId: string;
    orgId: string;
  }): Promise<void> {
    if (
      staticCampaignMap[orgId] &&
      staticCampaignMap[orgId]?.includes(campaignId)
    ) {
      this.logger.warn(
        `Campaign Id ${campaignId} is static and must be deleted by contacting support`,
      );
      throw new BadRequestException(
        `Campaign ${campaignId} is static and must be deleted by contacting support`,
      );
    }
    const campaign = new Campaign({ campaignId, orgId });
    await campaign.delete(this.datastoreService);
    return;
  }

  public async createCampaign(createCampaignDto: CreateCampaignDto) {
    const campaign = new Campaign(createCampaignDto);
    return campaign.create(this.datastoreService);
  }
}
import { Module } from '@nestjs/common';
import { CampaignService } from './campaign.service';
import { CampaignController } from './campaign.controller';
import { CampaignEntity } from './entities/campaign.entity';
import { DatastoreModule } from '../datastore/datastore.module';

@Module({
  controllers: [CampaignController],
  providers: [CampaignService, CampaignEntity],
  exports: [CampaignService],
  imports: [DatastoreModule],
})
export class CampaignModule {}
import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Post,
  Req,
  UnauthorizedException,
  UseGuards,
} from '@nestjs/common';
import { CampaignService } from './campaign.service';
import { AuthGuard } from '@nestjs/passport';
import { CreateCampaignDto } from './dto/create-campaign.dto';
import { AuthorizedRequest } from '../auth/authHeaderApiKey.strategy';

@Controller('campaign')
export class CampaignController {
  constructor(private readonly campaignService: CampaignService) {}

  @Post()
  @UseGuards(AuthGuard('user-api-key'))
  async createCampaign(
    @Body() campaign: CreateCampaignDto,
    @Req() authorizedRequest: AuthorizedRequest,
  ) {
    // eslint-disable-next-line
    // @ts-ignore
    const user = authorizedRequest?.headers?.user as {
      orgId: string;
    };
    if (!user) {
      throw new UnauthorizedException();
    }
    return this.campaignService.createCampaign({
      ...campaign,
      orgId: user.orgId,
    });
  }

  @Get()
  @UseGuards(AuthGuard('user-api-key'))
  async getCampaigns(@Req() authorizedRequest: AuthorizedRequest) {
    // eslint-disable-next-line
    // @ts-ignore
    const user = authorizedRequest?.headers?.user as {
      orgId: string;
    };
    if (!user) {
      throw new UnauthorizedException();
    }
    return this.campaignService.getCampaigns(user.orgId);
  }

  @Get(':campaignId')
  @UseGuards(AuthGuard('user-api-key'))
  async getCampaign(
    @Param('campaignId') campaignId: string,
    @Req() authorizedRequest: AuthorizedRequest,
  ) {
    // eslint-disable-next-line
    // @ts-ignore
    const user = authorizedRequest?.headers?.user as {
      orgId: string;
    };
    if (!user) {
      throw new UnauthorizedException();
    }
    return this.campaignService.getCampaign({ campaignId, orgId: user.orgId });
  }

  @Delete(':campaignId')
  @UseGuards(AuthGuard('user-api-key'))
  async deleteCampaign(
    @Param('campaignId') campaignId: string,
    @Req() authorizedRequest: AuthorizedRequest,
  ) {
    // eslint-disable-next-line
    // @ts-ignore
    const user = authorizedRequest?.headers?.user as {
      orgId: string;
    };
    if (!user) {
      throw new UnauthorizedException();
    }
    return this.campaignService.deleteCampaign({
      campaignId,
      orgId: user.orgId,
    });
  }
}

import { Db, MongoClient } from 'mongodb';
import { DataStore } from './datastore.interface';
import { datastoreContext } from './datastoreContext';
import { documentType } from './documentType';
import { Logger } from '@nestjs/common';
import * as fs from 'fs';
import { randomUUID } from 'crypto';

export class MongoDataStoreEntity implements DataStore {
  client: MongoClient;
  public rootPath = 'data';
  public db: Db;
  logger = new Logger(MongoDataStoreEntity.name);
  async init() {
    this.logger.debug('Initializing Mongo Datastore');
    this.logger.debug(`${process.cwd()}`);
    this.logger.debug(`${fs.readdirSync(process.cwd())}`);
    this.client = new MongoClient(`${process.env.MONGO_URI}`, {
      tls: process.env.STAGE === 'production',
      cert: fs.readFileSync(`global-bundle.pem`),
      monitorCommands: true,
      retryWrites: false,
      auth: {
        username: process.env.MONGO_USERNAME,
        password: process.env.MONGO_PASSWORD,
      },
    });
    await this.client.connect();
    this.db = this.client.db('data', { retryWrites: false });
  }
  private documentTypeToCollection(documentType: documentType) {
    return this.client.db().collection(documentType.toString());
  }
  async store(
    data: Record<any, any>,
    context?: datastoreContext & { documentTypes?: documentType[] },
  ): Promise<{ message: string; uniqueId: string }> {
    const {
      documentType,
      documentTypes,
      uniqueId,
      eventIdRef = randomUUID(),
    } = context;

    if (documentTypes) {
      // Store in multiple collections
      try {
        await Promise.all(
          documentTypes.map((dt) => {
            const collection = this.documentTypeToCollection(dt).collectionName;
            this.logger.debug(`Storing data in collection ${collection}`);
            return this.db
              .collection(collection)
              .updateOne(
                { id: uniqueId },
                { $set: { data, eventIdRef } },
                { upsert: true },
              );
          }),
        );
      } catch (e) {
        this.logger.error(`Error storing data: ${e}`);
        return { message: 'Error storing data', uniqueId };
      }
    } else {
      // Original single collection logic
      const collection =
        this.documentTypeToCollection(documentType).collectionName;
      this.logger.debug(`Storing data in collection ${collection}`);
      try {
        await this.db
          .collection(collection)
          .updateOne(
            { id: uniqueId },
            { $set: { data, eventIdRef } },
            { upsert: true },
          );
      } catch (e) {
        this.logger.error(`Error storing data: ${e}`);
        return { message: 'Error storing data', uniqueId };
      }
    }

    return { message: 'Data stored successfully', uniqueId };
  }

  async increment(
    data: Record<any, any>,
    context: datastoreContext & { documentTypes?: documentType[] },
  ) {
    const { documentType, documentTypes } = context;
    const { id, ...rest } = data;
    this.logger.log(
      `Incrementing data in collection ${documentType}. id: ${id}`,
    );
    if (documentTypes) {
      // Increment in multiple collections

      await Promise.all(
        documentTypes.map((dt) => {
          const collection = this.documentTypeToCollection(dt).collectionName;
          this.logger.debug(`Incrementing data in collection ${collection}`);
          return this.db
            .collection(collection)
            .updateOne({ id }, { $inc: rest });
        }),
      );
    } else {
      // Original single collection logic
      const collection =
        this.documentTypeToCollection(documentType).collectionName;
      this.logger.debug(`Incrementing data in collection ${collection}`);
      await this.db.collection(collection).updateOne({ id }, { $inc: rest });
    }

    return { message: 'Data incremented successfully' };
  }
  async remove(
    id: string,
    context: datastoreContext & { documentTypes?: documentType[] },
  ): Promise<{ message: string }> {
    const { documentType, documentTypes } = context;

    if (documentTypes) {
      // Remove from multiple collections
      await Promise.all(
        documentTypes.map((dt) => {
          const collection = this.documentTypeToCollection(dt).collectionName;
          this.logger.debug(`Removing data from collection ${collection}`);
          return this.db.collection(collection).deleteOne({ id });
        }),
      );
    } else {
      // Original single collection logic
      const collection =
        this.documentTypeToCollection(documentType).collectionName;
      this.logger.debug(`Removing data from collection ${collection}`);
      await this.db.collection(collection).deleteOne({ id });
    }

    return { message: 'Data removed successfully' };
  }

  async getById(
    id: string,
    context: datastoreContext & { documentTypes?: documentType[] },
  ): Promise<Record<any, any> | Record<any, any>[]> {
    const { documentType, documentTypes } = context;

    if (documentTypes) {
      // Search in multiple collections
      const results = await Promise.all(
        documentTypes.map(async (dt) => {
          const collection = this.documentTypeToCollection(dt).collectionName;
          this.logger.debug(
            `Getting data from collection ${collection} for ID: ${id}`,
          );
          const document = await this.db.collection(collection).findOne({ id });
          return document?.data
            ? { ...document.data, _collection: collection }
            : null;
        }),
      );

      const validResults = results.filter((result) => result !== null);
      return validResults.length > 0 ? validResults : undefined;
    } else {
      // Original single collection logic
      const collection =
        this.documentTypeToCollection(documentType).collectionName;
      this.logger.debug(
        `Getting data from collection ${collection} for ID: ${id}`,
      );
      const document = await this.db.collection(collection).findOne({ id });
      return document?.data;
    }
  }

  async getByPattern(
    pattern: string,
    context: datastoreContext & { documentTypes?: documentType[] },
  ): Promise<Record<any, any>[]> {
    const { documentType, documentTypes } = context;

    if (documentTypes) {
      // Search in multiple collections
      const results = await Promise.all(
        documentTypes.map(async (dt) => {
          const collection = this.documentTypeToCollection(dt).collectionName;
          this.logger.debug(`Getting data from collection ${collection}`);
          const documents = await this.db
            .collection(collection)
            .find({
              id: { $regex: pattern },
            })
            .toArray();
          return documents.map((doc) => ({
            ...doc.data,
            _collection: collection,
          }));
        }),
      );

      const allDocuments = results.flat();
      if (allDocuments.length > 0) {
        return allDocuments;
      }
    } else {
      // Original single collection logic
      const collection =
        this.documentTypeToCollection(documentType).collectionName;
      this.logger.debug(`Getting data from collection ${collection}`);
      const documents = await this.db
        .collection(collection)
        .find({
          id: { $regex: pattern },
        })
        .toArray();

      if (documents && documents.length > 0) {
        return documents.map((doc) => doc.data);
      }
    }

    return [];
  }
  async getByField(
    fieldKey: string,
    fieldValue: any,
    context: datastoreContext & { documentTypes?: documentType[] },
    pagination?: { page: number; pageSize: number },
  ): Promise<Record<any, any>[]> {
    const { documentType, documentTypes } = context;

    // If documentTypes array is provided, search across multiple collections
    const collectionsToSearch = documentTypes
      ? documentTypes.map(
          (dt) => this.documentTypeToCollection(dt).collectionName,
        )
      : [this.documentTypeToCollection(documentType).collectionName];

    this.logger.debug(
      `Searching collections ${collectionsToSearch.join(', ')} for field ${fieldKey}`,
    );
    // Execute parallel queries across all collections

    const results = await Promise.all(
      collectionsToSearch.map(async (collection) => {
        let documents;
        if (pagination) {
          documents = await this.db
            .collection(collection)
            .find({
              [fieldKey]: fieldValue,
            })
            .skip(pagination.page * pagination.pageSize)
            .limit(pagination.pageSize)
            .toArray();
        } else {
          documents = await this.db
            .collection(collection)
            .find({
              [fieldKey]: fieldValue,
            })
            .toArray();
        }
        return documents.map((doc) => ({
          ...doc.data,
          _collection: collection, // Optional: Include source collection
        }));
      }),
    );

    // Flatten results from all collections
    const allDocuments = results.flat();

    this.logger.log(
      `Found ${allDocuments.length} documents across ${collectionsToSearch.length} collections`,
    );

    return allDocuments.length > 0 ? allDocuments : undefined;
  }

  async getByFieldAndAggregate(
    fieldKey: string,
    fieldValue: any,
    context: datastoreContext & { documentTypes?: documentType[] },
    customAggregation: Array<any>,
    pagination?: { page: number; pageSize: number },
  ) {
    const { documentType, documentTypes } = context;

    // Determine which collection(s) to search
    const collectionsToSearch = documentTypes
      ? documentTypes.map(
          (dt) => this.documentTypeToCollection(dt).collectionName,
        )
      : [this.documentTypeToCollection(documentType).collectionName];

    this.logger.debug(
      `getByFieldAndAggregate: Searching collections ${collectionsToSearch.join(', ')} for ${fieldKey}=${fieldValue}.`,
    );

    // Build a base pipeline that includes matching on the given fieldKey/fieldValue
    // then spread in any custom aggregation stages the caller provided.
    const buildPipeline = (scopedPagination?: {
      page: number;
      pageSize: number;
    }) => {
      const pipeline = [
        { $match: { [fieldKey]: fieldValue } },
        ...customAggregation,
      ];

      // If pagination is requested, apply skip/limit at the end
      if (scopedPagination) {
        pipeline.push({
          $skip: scopedPagination.page * scopedPagination.pageSize,
        });
        pipeline.push({ $limit: scopedPagination.pageSize });
      }

      return pipeline;
    };

    // For each collection, run the aggregation pipeline
    const resultsPerCollection = await Promise.all(
      collectionsToSearch.map(async (collection) => {
        this.logger.debug(`Running aggregation on collection: ${collection}`);

        const pipelineResult = await this.db
          .collection(collection)
          .aggregate(buildPipeline(pagination))
          .toArray();

        // Optionally annotate results with the source collection
        return pipelineResult.map((doc) => ({
          ...doc,
          _collection: collection,
        }));
      }),
    );

    // Flatten all results and return
    const allResults = resultsPerCollection.flat();
    return allResults;
  }

  async migrate(SOURCE_COLLECTION, TARGET_COLLECTION) {
    try {
      const sourceCollection = this.db.collection(SOURCE_COLLECTION);
      const targetCollection = this.db.collection(TARGET_COLLECTION);

      // Process documents in the source collection
      const cursor = sourceCollection.find();
      const BATCH_SIZE = 1000;
      let batch = [];
      let processedCount = 0;

      while (await cursor.hasNext()) {
        const doc = await cursor.next();

        // Transform campaignIds to the new format
        if (doc.data && doc.data.campaignIds) {
          const newDocument = {
            ...doc,
            data: {
              ...doc.data,
              campaignIds: Object.entries(doc.data.campaignIds).map(
                ([id, value]) => ({
                  id,
                  // eslint-disable-next-line
                  // @ts-ignore
                  ...value,
                }),
              ),
            },
          };

          // Remove the _id field to avoid duplicate key errors in the new collection
          delete newDocument._id;
          batch.push(newDocument);

          // Insert batch when full
          if (batch.length === BATCH_SIZE) {
            await targetCollection.insertMany(batch);
            processedCount += batch.length;
            this.logger.log(`Inserted ${processedCount} documents so far`);
            batch = [];
          }
        } else {
          this.logger.log(
            `Skipping document with missing data or campaignIds field: ${doc._id}`,
          );
        }
      }

      // Insert remaining documents
      if (batch.length > 0) {
        await targetCollection.insertMany(batch);
        processedCount += batch.length;
      }

      this.logger.log(
        `Transformation completed. Inserted ${processedCount} documents into ${TARGET_COLLECTION}.`,
      );
    } catch (error) {
      this.logger.error('An error occurred:', error);
    }
  }

  async getPageCount({
    collection,
    fieldKey,
    fieldValue,
  }: {
    collection: string;
    fieldKey: string;
    fieldValue: any;
  }) {
    const count = await this.db
      .collection(collection)
      .countDocuments({ [fieldKey]: fieldValue });
    return count;
  }
}
