import { DataStore } from './datastore.interface';
import * as fs from 'fs';
import { datastoreContext } from './datastoreContext';
import { NotImplementedException } from '@nestjs/common';

export class FileSystemDataStoreEntity implements DataStore {
  client: typeof fs;
  public rootPath = 'data';
  async init() {
    this.client = fs;
  }

  async store(
    data: Record<any, any>,
    context?: datastoreContext,
  ): Promise<{ message: string; uniqueId: string }> {
    const path = context?.uniqueId ? context.uniqueId : randomUUID();
    // if the path doesn't exist, create it
    if (!fs.existsSync(`${this.rootPath}/${path}.json`)) {
      // If the path contains directories that don't exist, create them
      const pathParts = path.split('/');
      if (pathParts.length > 1) {
        pathParts.pop();
        const pathToCreate = pathParts.join('/');
        fs.mkdirSync(`${this.rootPath}/${pathToCreate}`, { recursive: true });
      } else {
        fs.mkdirSync(`${this.rootPath}/${path}`, { recursive: true });
      }
    }
    this.client.writeFileSync(
      `${this.rootPath}/${path}.json`,
      JSON.stringify(data),
    );
    return {
      message: 'Data stored successfully',
      uniqueId: `${this.rootPath}/${path}`,
    };
  }
  async remove(id: string): Promise<{ message: string }> {
    this.client.unlinkSync(`${this.rootPath}/${id}.json`);
    return { message: 'Data removed successfully' };
  }

  async getById(id: string): Promise<Record<any, any>> {
    return JSON.parse(
      this.client.readFileSync(`${this.rootPath}/${id}.json`, 'utf8'),
    );
  }

  async getByPattern(pattern: string): Promise<Record<any, any>[]> {
    const files = this.client.readdirSync(this.rootPath);
    const data = files
      .filter((file) => file.includes(pattern))
      .map((file) => {
        return JSON.parse(
          this.client.readFileSync(`${this.rootPath}/${file}`, 'utf8'),
        );
      });
    return data;
  }
  async getByField(fieldKey, fieldValue, context): Promise<Record<any, any>[]> {
    throw new NotImplementedException('Method not implemented');
    return;
  }
}
