import {
  INestApplication,
  NestInterceptor,
  ValidationPipe,
} from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import {
  AppModule,
  EnricherAppModule,
  PublicAppModule,
  WebhookAppModule,
} from './app.module';
import { DatastoreService } from './datastore/datastore.service';
import { Logger } from 'nestjs-pino';
import { useContainer } from 'class-validator';
import { RequestLoggingInterceptor } from './interceptor/requstLogginInterceptor';
import { ClientInformationInterceptor } from './interceptor/clientInformation.interceptor';

export abstract class Initializer {
  protected app: INestApplication;

  abstract getModule(): any;

  protected getGlobalInterceptors(): NestInterceptor[] {
    const datastoreService = this.app.get(DatastoreService);
    return [
      new RequestLoggingInterceptor(),
      new ClientInformationInterceptor(datastoreService),
    ];
  }

  protected applyExtraConfig(): void {}

  public async init(): Promise<void> {
    this.app = await NestFactory.create(this.getModule(), {
      bufferLogs: true,
    });

    this.app.useLogger(this.app.get(Logger));
    this.app.useGlobalInterceptors(...this.getGlobalInterceptors());
    this.app.useGlobalPipes(
      new ValidationPipe({ whitelist: true, transform: true }),
    );
    useContainer(this.app.select(this.getModule()), { fallbackOnErrors: true });

    this.applyExtraConfig();

    const server = this.app.getHttpServer();
    server.setTimeout(60 * 60 * 1000);
    server.keepAliveTimeout = 3610 * 1000;
    server.headersTimeout = 3620 * 1000;

    await this.app.listen(3000);
  }
}

export class EnricherWorkerInitializer extends Initializer {
  getModule() {
    return EnricherAppModule;
  }
}

export class StateMachineInitializer extends Initializer {
  getModule() {
    return AppModule;
  }
}

export class WebhookInitializer extends Initializer {
  getModule() {
    return WebhookAppModule;
  }
}

export class PublicInitializer extends Initializer {
  getModule() {
    return PublicAppModule;
  }

  protected getGlobalInterceptors(): NestInterceptor[] {
    const datastoreService = this.app.get(DatastoreService);
    return [new ClientInformationInterceptor(datastoreService)];
  }

  protected applyExtraConfig() {
    this.app.enableCors({
      origin: [
        'http://localhost:3000',
        'http://localhost:3001',
        'https://champ.portal.tenex.email',
        'https://api.prod.tenex.email',
        'https://public.prod.tenex.email',
      ],
    });
  }
}

