import {
  IsArray,
  IsNumber,
  IsOptional,
  IsString,
  Min,
} from 'class-validator';

/**
 * The mapped band of an email account deliverability score.
 * The raw (numeric) deliverability score is the smartlead warmup reputation.
 *
 * 100      -> High
 * 98 - 99  -> Medium
 * 95 - 97  -> Low
 * < 95     -> Burned
 * missing  -> Unknown
 */
export enum DeliverabilityScore {
  High = 'High',
  Medium = 'Medium',
  Low = 'Low',
  Burned = 'Burned',
  Unknown = 'Unknown',
}

/**
 * Defaults taken from the email infrastructure spec.
 * A campaign runs for 10 days and every inbox sends 20 emails per day.
 */
export const DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN = 10;
export const DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY = 20;

/**
 * Maps a numeric deliverability score (smartlead warmup reputation)
 * onto its {@link DeliverabilityScore} band.
 */
export function mapDeliverabilityScore(
  deliverabilityScore?: number,
): DeliverabilityScore {
  if (
    deliverabilityScore === undefined ||
    deliverabilityScore === null ||
    Number.isNaN(Number(deliverabilityScore))
  ) {
    return DeliverabilityScore.Unknown;
  }
  const score = Number(deliverabilityScore);
  if (score >= 100) {
    return DeliverabilityScore.High;
  }
  if (score >= 98) {
    return DeliverabilityScore.Medium;
  }
  if (score >= 95) {
    return DeliverabilityScore.Low;
  }
  return DeliverabilityScore.Burned;
}

