import {
  Injectable,
  InternalServerErrorException,
  Logger,
  NotFoundException,
  Optional,
} from '@nestjs/common';
import { DatastoreService } from '../../datastore/datastore.service';
import { documentType } from '../../datastore/entites/documentType';
import { StoreDataDto } from '../../datastore/dto/store.dto';
import {
  DeliverabilityScore,
  EmailAccountDto,
  mapDeliverabilityScore,
} from '../dto/emailAccount.dto';

export { DeliverabilityScore, mapDeliverabilityScore };

export const EMAIL_ACCOUNT_DOCUMENT_TYPE = documentType.EMAIL_ACCOUNT;
export const DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE = 100;

/**
 * The shape of an email account (inbox) as returned by the smartlead api.
 * GET https://server.smartlead.ai/api/v1/email-accounts/{id}
 */
export type SmartleadInbox = {
  id?: number | string;
  created_at?: string;
  updated_at?: string;
  from_name?: string;
  from_email?: string;
  client_id?: number | string;
  message_per_day?: number;
  warmup_details?: {
    warmup_reputation?: string | number;
    status?: string;
  };
  warmup_reputation?: string | number;
};

/**
 * An email account is a warmed up sending inbox living inside of smartlead.
 * It is uniquely identified by its smartlead inbox id.
 */
export class EmailAccount {
  /** Unique id of the inbox inside of smartlead */
  smartleadInboxId: string;
  /** The smartlead client (customer) the inbox belongs to */
  smartleadClientId: string;
  email: string;
  /** Derived from the email address */
  domain: string;
  tags: string[];
  campaignIds: string[];
  numberOfCampaignAssociated: number;
  /** The numeric warmup reputation reported by smartlead */
  deliverabilityScore?: number;
  /** The mapped band of the numeric deliverability score */
  deliverabilityScoreBand: DeliverabilityScore;
  createdAt: string;
  updatedAt: string;

  constructor(partial: Partial<EmailAccount> | Partial<EmailAccountDto>) {
    Object.assign(this, partial ? partial : {});
    // Datastore implementations decorate documents with internal metadata.
    ['_collection', '_id', 'eventIdRef'].forEach((key) => {
      if (key in this) {
        delete this[key];
      }
    });
    if (this.smartleadInboxId !== undefined && this.smartleadInboxId !== null) {
      this.smartleadInboxId = `${this.smartleadInboxId}`;
    }
    if (
      this.smartleadClientId !== undefined &&
      this.smartleadClientId !== null
    ) {
      this.smartleadClientId = `${this.smartleadClientId}`;
    }
    this.tags = EmailAccount.uniqueList(this.tags);
    this.campaignIds = EmailAccount.uniqueList(this.campaignIds);
    this.numberOfCampaignAssociated = this.campaignIds.length;
    const derivedDomain = EmailAccount.getDomainFromEmail(this.email);
    this.domain = derivedDomain ? derivedDomain : this.domain;
    this.deliverabilityScore = EmailAccount.parseDeliverabilityScore(
      this.deliverabilityScore,
    );
    this.deliverabilityScoreBand = mapDeliverabilityScore(
      this.deliverabilityScore,
    );
  }

  /** Alias of {@link deliverabilityScoreBand} */
  get deliverabilityBand(): DeliverabilityScore {
    return mapDeliverabilityScore(this.deliverabilityScore);
  }

  /** Alias of {@link deliverabilityScoreBand} */
  get deliverabilityStatus(): DeliverabilityScore {
    return mapDeliverabilityScore(this.deliverabilityScore);
  }

  getDeliverabilityScoreBand(): DeliverabilityScore {
    return mapDeliverabilityScore(this.deliverabilityScore);
  }

  /**
   * Associates the inbox with a campaign. The association is idempotent, a
   * campaign is only ever tracked once.
   * Returns true when the account changed.
   */
  associateCampaign(campaignId: string): boolean {
    if (!campaignId) {
      return false;
    }
    if (this.campaignIds.includes(campaignId)) {
      this.numberOfCampaignAssociated = this.campaignIds.length;
      return false;
    }
    this.campaignIds = [...this.campaignIds, campaignId];
    this.numberOfCampaignAssociated = this.campaignIds.length;
    return true;
  }

  static uniqueList(list?: string[]): string[] {
    if (!list || !Array.isArray(list)) {
      return [];
    }
    return list
      .filter((item) => item !== undefined && item !== null && item !== '')
      .map((item) => `${item}`)
      .filter((item, index, self) => self.indexOf(item) === index);
  }

  static getDomainFromEmail(email?: string): string | undefined {
    if (!email || typeof email !== 'string' || !email.includes('@')) {
      return undefined;
    }
    const domain = email.split('@').pop();
    return domain ? domain.trim().toLowerCase() : undefined;
  }

  /**
   * Smartlead reports the warmup reputation as a percentage string ("100%").
   */
  static parseDeliverabilityScore(
    warmupReputation?: string | number,
  ): number | undefined {
    if (warmupReputation === undefined || warmupReputation === null) {
      return undefined;
    }
    if (typeof warmupReputation === 'number') {
      return Number.isFinite(warmupReputation) ? warmupReputation : undefined;
    }
    const parsed = parseFloat(`${warmupReputation}`.replace('%', '').trim());
    return Number.isFinite(parsed) ? parsed : undefined;
  }

  static getDeliverabilityScoreBand(
    deliverabilityScore?: number,
  ): DeliverabilityScore {
    return mapDeliverabilityScore(deliverabilityScore);
  }
}

/**
 * Persistence + smartlead hydration for email accounts (sending inboxes).
 */
@Injectable()
export class EmailInfraEntity {
  private readonly logger = new Logger(EmailInfraEntity.name);
  constructor(
    @Optional() private readonly datastoreService?: DatastoreService,
  ) {}

  private get datastore(): DatastoreService {
    if (!this.datastoreService) {
      throw new InternalServerErrorException(
        'No datastore configured for email accounts',
      );
    }
    return this.datastoreService;
  }

  /**
   * Creates (or updates) an email account. The creation time and the warmup
   * reputation are always hydrated from smartlead.
   */
  async create(emailAccount: EmailAccountDto): Promise<EmailAccount> {
    if (!emailAccount?.smartleadInboxId) {
      throw new NotFoundException('smartleadInboxId is required');
    }
    const smartleadInboxId = `${emailAccount.smartleadInboxId}`;
    const inbox = await this.getSmartleadInbox(smartleadInboxId);
    const existingAccount = await this.find(smartleadInboxId);
    const createdAt =
      inbox?.created_at ??
      emailAccount?.createdAt ??
      existingAccount?.createdAt ??
      new Date().toISOString();
    const deliverabilityScore =
      EmailAccount.parseDeliverabilityScore(
        inbox?.warmup_details?.warmup_reputation ?? inbox?.warmup_reputation,
      ) ?? EmailAccount.parseDeliverabilityScore(emailAccount?.deliverabilityScore);
    const account = new EmailAccount({
      ...(existingAccount ? existingAccount : {}),
      ...emailAccount,
      smartleadInboxId,
      email: emailAccount?.email
        ? emailAccount.email
        : (existingAccount?.email ?? inbox?.from_email),
      smartleadClientId: emailAccount?.smartleadClientId
        ? `${emailAccount.smartleadClientId}`
        : (existingAccount?.smartleadClientId ??
          (inbox?.client_id !== undefined && inbox?.client_id !== null
            ? `${inbox.client_id}`
            : undefined)),
      tags: [
        ...EmailAccount.uniqueList(existingAccount?.tags),
        ...EmailAccount.uniqueList(emailAccount?.tags),
      ],
      campaignIds: [
        ...EmailAccount.uniqueList(existingAccount?.campaignIds),
        ...EmailAccount.uniqueList(emailAccount?.campaignIds),
      ],
      deliverabilityScore,
      createdAt,
    });
    return this.save(account);
  }

  /**
   * Persists an already built email account.
   */
  async save(emailAccount: EmailAccount): Promise<EmailAccount> {
    const account =
      emailAccount instanceof EmailAccount
        ? emailAccount
        : new EmailAccount(emailAccount);
    account.updatedAt = new Date().toISOString();
    if (!account.createdAt) {
      account.createdAt = account.updatedAt;
    }
    this.logger.log(`Storing email account ${account.smartleadInboxId}`);
    await this.datastore.store(
      new StoreDataDto({
        data: account,
        context: {
          uniqueId: account.smartleadInboxId,
          documentType: documentType.EMAIL_ACCOUNT,
        },
      }),
    );
    return account;
  }

  /**
   * Looks an email account up by its smartlead inbox id.
   * Returns undefined when the account does not exist.
   */
  async find(smartleadInboxId: string): Promise<EmailAccount | undefined> {
    if (!smartleadInboxId) {
      return undefined;
    }
    const id = `${smartleadInboxId}`;
    const byField = await this.getByField('data.smartleadInboxId', id);
    if (byField.length > 0) {
      return byField[0];
    }
    const byId = await this.getById(id);
    return byId;
  }

  async read(smartleadInboxId: string): Promise<EmailAccount> {
    const account = await this.find(smartleadInboxId);
    if (!account) {
      throw new NotFoundException(
        `Email account ${smartleadInboxId} not found`,
      );
    }
    return account;
  }

  async findByEmail(email: string): Promise<EmailAccount | undefined> {
    if (!email) {
      return undefined;
    }
    const accounts = await this.getByField('data.email', email);
    return accounts[0];
  }

  async readByEmail(email: string): Promise<EmailAccount> {
    const account = await this.findByEmail(email);
    if (!account) {
      throw new NotFoundException(`Email account ${email} not found`);
    }
    return account;
  }

  async readBySmartleadClientId(
    smartleadClientId: string,
  ): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      return [];
    }
    return this.getByField('data.smartleadClientId', `${smartleadClientId}`);
  }

  async readAll({
    page,
    pageSize,
  }: { page?: number; pageSize?: number } = {}): Promise<EmailAccount[]> {
    const res = await this.datastore.getByField({
      fieldKey: 'data.smartleadInboxId',
      fieldValue: { $exists: true },
      documentType: documentType.EMAIL_ACCOUNT,
      pagination: {
        page: page === undefined || page === null ? 0 : page,
        pageSize:
          pageSize === undefined || pageSize === null
            ? DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE
            : pageSize,
      },
    });
    return EmailInfraEntity.toEmailAccounts(res);
  }

  async delete(smartleadInboxId: string): Promise<{ message: string }> {
    const id = `${smartleadInboxId}`;
    this.logger.log(`Deleting email account ${id}`);
    await this.datastore.remove({
      id,
      documentType: documentType.EMAIL_ACCOUNT,
    });
    return { message: 'Email account deleted successfully' };
  }

  /**
   * Fetches an inbox from smartlead. Throws a NotFoundException when the
   * inbox does not exist inside of smartlead.
   */
  async getSmartleadInbox(smartleadInboxId: string): Promise<SmartleadInbox> {
    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
    const url = `https://server.smartlead.ai/api/v1/email-accounts/${smartleadInboxId}?api_key=${apiKey}`;
    this.logger.log(`Getting smartlead inbox ${smartleadInboxId}`);
    const res = await fetch(url);
    if (res?.status === 404 || res?.ok === false) {
      this.logger.error(`Smartlead inbox not found: ${smartleadInboxId}`);
      throw new NotFoundException(
        `Email account ${smartleadInboxId} not found in smartlead`,
      );
    }
    let inbox: SmartleadInbox;
    try {
      inbox = await res.json();
    } catch (error) {
      this.logger.error(
        `Unable to parse the smartlead inbox response for ${smartleadInboxId}: ${error}`,
      );
      throw new NotFoundException(
        `Email account ${smartleadInboxId} not found in smartlead`,
      );
    }
    if (!inbox || Object.keys(inbox).length === 0) {
      this.logger.error(`Smartlead inbox not found: ${smartleadInboxId}`);
      throw new NotFoundException(
        `Email account ${smartleadInboxId} not found in smartlead`,
      );
    }
    return inbox;
  }

  private async getById(id: string): Promise<EmailAccount | undefined> {
    if (typeof this.datastore.getById !== 'function') {
      return undefined;
    }
    const res = await this.datastore.getById({
      id,
      documentType: documentType.EMAIL_ACCOUNT,
    });
    return EmailInfraEntity.toEmailAccounts(res)[0];
  }

  private async getByField(
    fieldKey: string,
    fieldValue: string | Record<string, any>,
  ): Promise<EmailAccount[]> {
    const res = await this.datastore.getByField({
      fieldKey,
      fieldValue,
      documentType: documentType.EMAIL_ACCOUNT,
    });
    return EmailInfraEntity.toEmailAccounts(res);
  }

  static toEmailAccounts(res: any): EmailAccount[] {
    const data = res && 'data' in Object(res) ? res.data : res;
    if (data === undefined || data === null) {
      return [];
    }
    const documents = Array.isArray(data) ? data : [data];
    return documents
      .filter((document) => document !== undefined && document !== null)
      .map((document) =>
        document instanceof EmailAccount
          ? document
          : new EmailAccount(document?.data ? document.data : document),
      )
      .filter((account) => !!account.smartleadInboxId);
  }
}

