arguments.content:
export {
  EmailAccount,
  EmailInfraEntity,
  EmailAccountEntity,
  EMAIL_ACCOUNT_DOCUMENT_TYPE,
  DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE,
  DeliverabilityScore,
  mapDeliverabilityScore,
} from './emailinfra.entity';
export type { SmartleadInbox } from './emailinfra.entity';

import {
  BadRequestException,
  Injectable,
  Logger,
  NotFoundException,
  Optional,
} from '@nestjs/common';
import {
  DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
  DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  EmailAccountDto,
  EmailAccountListDto,
  EmailAccountPaginationDto,
} from './dto/emailAccount.dto';
import {
  DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE,
  EmailAccount,
  EmailInfraEntity,
} from './entities/emailinfra.entity';
import { DatastoreService } from '../datastore/datastore.service';

@Injectable()
export class EmailinfraService {
  private readonly logger = new Logger(EmailinfraService.name);
  private lazyEmailInfraEntity: EmailInfraEntity;
  constructor(
    @Optional() private readonly emailInfraEntity?: EmailInfraEntity,
    @Optional() private readonly datastoreService?: DatastoreService,
  ) {}

  private get entity(): EmailInfraEntity {
    if (this.emailInfraEntity) {
      return this.emailInfraEntity;
    }
    if (!this.lazyEmailInfraEntity) {
      this.lazyEmailInfraEntity = new EmailInfraEntity(this.datastoreService);
    }
    return this.lazyEmailInfraEntity;
  }

  /**
   * Returns the best sending inboxes of a smartlead client for a campaign.
   *
   * The size of the required pool of inboxes is:
   *   floor(total emails / days in campaign / emails per inbox per day)
   *
   * The inboxes of the client are then ranked by:
   *   1. deliverability score, descending (the best warmed up inboxes first)
   *   2. number of campaigns associated, ascending (the least used first)
   *   3. number of other inboxes on the same domain, ascending
   *   4. creation time, ascending (the oldest inboxes first)
   *
   * See: https://app.clickup.com/18036112/v/dc/h6dcg-8771/h6dcg-44571
   *
   * Example:
   *  500 emails to send, 10 days in the campaign, 20 emails per inbox per day
   *  -> floor(500 / 10 / 20) = 2 inboxes.
   */
  async getBestEmailAccountsForCampaign({
    smartleadClientId,
    campaignId,
    numberOfDaysInCampaign,
    totalNumberOfEmailsToSend,
    numberOfEmailsPerInboxPerDay,
  }: EmailAccountListDto): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      throw new BadRequestException('smartleadClientId is required');
    }
    const numberOfInboxesRequired = this.getNumberOfInboxesRequired({
      totalNumberOfEmailsToSend,
      numberOfDaysInCampaign,
      numberOfEmailsPerInboxPerDay,
    });
    this.logger.log(
      `Getting the best ${numberOfInboxesRequired} email accounts of client ${smartleadClientId} for campaign ${campaignId}`,
    );
    if (numberOfInboxesRequired <= 0) {
      this.logger.warn(
        `No email accounts required for campaign ${campaignId}. Total emails to send: ${totalNumberOfEmailsToSend}`,
      );
      return [];
    }
    const emailAccounts =
      await this.entity.readBySmartleadClientId(smartleadClientId);
    if (!emailAccounts || emailAccounts.length === 0) {
      this.logger.warn(
        `No email accounts found for smartlead client ${smartleadClientId}`,
      );
      return [];
    }
    const numberOfInboxesPerDomain = emailAccounts.reduce(
      (acc, emailAccount) => {
        const domain = emailAccount?.domain;
        if (domain) {
          acc[domain] = (acc[domain] ? acc[domain] : 0) + 1;
        }
        return acc;
      },
      {} as Record<string, number>,
    );
    const numberOfOtherInboxesOnDomain = (emailAccount: EmailAccount) => {
      const domain = emailAccount?.domain;
      if (!domain || !numberOfInboxesPerDomain[domain]) {
        return 0;
      }
      return numberOfInboxesPerDomain[domain] - 1;
    };
    const rankedEmailAccounts = [...emailAccounts].sort((a, b) => {
      const deliverabilityScoreDifference =
        (b?.deliverabilityScore ? b.deliverabilityScore : 0) -
        (a?.deliverabilityScore ? a.deliverabilityScore : 0);
      if (deliverabilityScoreDifference !== 0) {
        return deliverabilityScoreDifference;
      }
      const campaignDifference =
        (a?.numberOfCampaignAssociated ? a.numberOfCampaignAssociated : 0) -
        (b?.numberOfCampaignAssociated ? b.numberOfCampaignAssociated : 0);
      if (campaignDifference !== 0) {
        return campaignDifference;
      }
      const domainDifference =
        numberOfOtherInboxesOnDomain(a) - numberOfOtherInboxesOnDomain(b);
      if (domainDifference !== 0) {
        return domainDifference;
      }
      return (
        new Date(a?.createdAt ? a.createdAt : 0).getTime() -
        new Date(b?.createdAt ? b.createdAt : 0).getTime()
      );
    });
    const bestEmailAccounts = rankedEmailAccounts.slice(
      0,
      numberOfInboxesRequired,
    );
    this.logger.log(
      `Found ${bestEmailAccounts.length} email accounts for campaign ${campaignId}`,
    );
    return bestEmailAccounts;
  }

  /**
   * floor(total emails / days in campaign / emails per inbox per day)
   */
  getNumberOfInboxesRequired({
    totalNumberOfEmailsToSend,
    numberOfDaysInCampaign,
    numberOfEmailsPerInboxPerDay,
  }: {
    totalNumberOfEmailsToSend: number;
    numberOfDaysInCampaign?: number;
    numberOfEmailsPerInboxPerDay?: number;
  }): number {
    const daysInCampaign = numberOfDaysInCampaign
      ? numberOfDaysInCampaign
      : DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN;
    const emailsPerInboxPerDay = numberOfEmailsPerInboxPerDay
      ? numberOfEmailsPerInboxPerDay
      : DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY;
    if (!totalNumberOfEmailsToSend || totalNumberOfEmailsToSend <= 0) {
      return 0;
    }
    return Math.floor(
      totalNumberOfEmailsToSend / daysInCampaign / emailsPerInboxPerDay,
    );
  }

  /**
   * Associates a list of inboxes with a campaign.
   *
   * The same inbox id passed multiple times is only handled once and an
   * inbox is only ever associated once with a campaign (idempotent).
   * When any of the requested inboxes does not exist the whole request is
   * rejected and nothing is written.
   */
  async associateEmailAccountsWithCampaign({
    emailAccountIds,
    campaignId,
  }: {
    emailAccountIds: string[];
    campaignId: string;
  }): Promise<EmailAccount[]> {
    if (!campaignId) {
      throw new BadRequestException('campaignId is required');
    }
    const uniqueEmailAccountIds = EmailAccount.uniqueList(emailAccountIds);
    if (uniqueEmailAccountIds.length === 0) {
      throw new BadRequestException('emailAccountIds is required');
    }
    this.logger.log(
      `Associating email accounts ${uniqueEmailAccountIds.join(', ')} with campaign ${campaignId}`,
    );
    const emailAccounts = await Promise.all(
      uniqueEmailAccountIds.map(async (emailAccountId) => ({
        emailAccountId,
        emailAccount: await this.entity.find(emailAccountId),
      })),
    );
    const missingEmailAccountIds = emailAccounts
      .filter(({ emailAccount }) => !emailAccount)
      .map(({ emailAccountId }) => emailAccountId);
    if (missingEmailAccountIds.length > 0) {
      this.logger.error(
        `Email accounts not found: ${missingEmailAccountIds.join(', ')}`,
      );
      throw new NotFoundException(
        `Email accounts not found: ${missingEmailAccountIds.join(', ')}`,
      );
    }
    const associatedEmailAccounts: EmailAccount[] = [];
    for (const { emailAccount } of emailAccounts) {
      const hasChanged = emailAccount.associateCampaign(campaignId);
      if (!hasChanged) {
        this.logger.log(
          `Email account ${emailAccount.smartleadInboxId} is already associated with campaign ${campaignId}`,
        );
        associatedEmailAccounts.push(emailAccount);
        continue;
      }
      associatedEmailAccounts.push(await this.entity.save(emailAccount));
    }
    return associatedEmailAccounts;
  }

  /**
   * Saves an email account. The creation time and the deliverability score
   * (the warmup reputation) are hydrated from smartlead.
   */
  async saveEmailAccount(emailAccount: EmailAccountDto): Promise<EmailAccount> {
    if (!emailAccount?.smartleadInboxId) {
      throw new BadRequestException('smartleadInboxId is required');
    }
    this.logger.log(
      `Saving email account ${emailAccount.smartleadInboxId} for smartlead client ${emailAccount?.smartleadClientId}`,
    );
    return this.entity.create(emailAccount);
  }

  /**
   * Gets an email account by its smartlead inbox id.
   */
  async getEmailAccount(
    emailAccount: EmailAccountDto | Partial<EmailAccountDto> | string,
  ): Promise<EmailAccount> {
    const smartleadInboxId =
      typeof emailAccount === 'string'
        ? emailAccount
        : emailAccount?.smartleadInboxId;
    if (!smartleadInboxId) {
      const email =
        typeof emailAccount === 'string' ? undefined : emailAccount?.email;
      if (email) {
        return this.getEmailAccountByEmail(email);
      }
      throw new BadRequestException('smartleadInboxId is required');
    }
    return this.entity.read(smartleadInboxId);
  }

  /**
   * Lists the email accounts, paginated.
   */
  async getAllEmailAccounts(
    pagination?: EmailAccountPaginationDto | number,
    pageSize?: number,
  ): Promise<EmailAccount[]> {
    const normalizedPagination =
      typeof pagination === 'number'
        ? { page: pagination, pageSize }
        : {
            page: pagination?.page,
            pageSize:
              pagination?.pageSize === undefined ? pageSize : pagination.pageSize,
          };
    const page = normalizedPagination.page ? normalizedPagination.page : 0;
    const size = normalizedPagination.pageSize
      ? normalizedPagination.pageSize
      : DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE;
    this.logger.log(`Getting all email accounts. Page ${page} size ${size}`);
    return this.entity.readAll({ page, pageSize: size });
  }

  async getEmailAccountByEmail(email: string): Promise<EmailAccount> {
    if (!email) {
      throw new BadRequestException('email is required');
    }
    this.logger.log(`Getting email account by email ${email}`);
    return this.entity.readByEmail(email);
  }

  async getEmailAccountBySmartleadClientId(
    smartleadClientId: string,
  ): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      throw new BadRequestException('smartleadClientId is required');
    }
    this.logger.log(
      `Getting email accounts for smartlead client ${smartleadClientId}`,
    );
    return this.entity.readBySmartleadClientId(smartleadClientId);
  }

  /**
   * Deletes an email account. Throws when the account does not exist.
   */
  async deleteEmailAccount(
    emailAccount: EmailAccountDto | Partial<EmailAccountDto> | string,
  ): Promise<{ message: string }> {
    const existingEmailAccount = await this.getEmailAccount(emailAccount);
    this.logger.log(
      `Deleting email account ${existingEmailAccount.smartleadInboxId}`,
    );
    return this.entity.delete(existingEmailAccount.smartleadInboxId);
  }

  /**
   * Imports a list of inboxes into the email account datastore. Used by the
   * email account import script.
   */
  async importEmailAccounts(emailAccounts: EmailAccountDto[]): Promise<{
    imported: EmailAccount[];
    failed: Array<{ smartleadInboxId: string; message: string }>;
  }> {
    const imported: EmailAccount[] = [];
    const failed: Array<{ smartleadInboxId: string; message: string }> = [];
    for (const emailAccount of emailAccounts ? emailAccounts : []) {
      try {
        imported.push(await this.saveEmailAccount(emailAccount));
      } catch (error) {
        this.logger.error(
          `Unable to import email account ${emailAccount?.smartleadInboxId}: ${error}`,
        );
        failed.push({
          smartleadInboxId: emailAccount?.smartleadInboxId,
          message: error?.message ? error.message : `${error}`,
        });
      }
    }
    return { imported, failed };
  }

  /**
   * Re-hydrates the deliverability score (warmup reputation) of an inbox
   * from smartlead. Used by the reputation sync script.
   */
  async syncEmailAccountDeliverabilityScore(
    smartleadInboxId: string,
  ): Promise<EmailAccount> {
    const emailAccount = await this.entity.read(smartleadInboxId);
    return this.entity.create(emailAccount);
  }

  /**
   * Re-hydrates the deliverability score of every known inbox.
   */
  async syncAllEmailAccountDeliverabilityScores({
    pageSize,
  }: { pageSize?: number } = {}): Promise<{
    synced: EmailAccount[];
    failed: Array<{ smartleadInboxId: string; message: string }>;
  }> {
    const size = pageSize ? pageSize : DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE;
    const synced: EmailAccount[] = [];
    const failed: Array<{ smartleadInboxId: string; message: string }> = [];
    let page = 0;
    // eslint-disable-next-line no-constant-condition
    while (true) {
      const emailAccounts = await this.entity.readAll({ page, pageSize: size });
      if (!emailAccounts || emailAccounts.length === 0) {
        break;
      }
      for (const emailAccount of emailAccounts) {
        try {
          synced.push(await this.entity.create(emailAccount));
        } catch (error) {
          this.logger.error(
            `Unable to sync email account ${emailAccount?.smartleadInboxId}: ${error}`,
          );
          failed.push({
            smartleadInboxId: emailAccount?.smartleadInboxId,
            message: error?.message ? error.message : `${error}`,
          });
        }
      }
      if (emailAccounts.length < size) {
        break;
      }
      page += 1;
    }
    return { synced, failed };
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Post,
  Query,
  UseGuards,
} from '@nestjs/common';
