/**
 * Imports the warmed up sending inboxes of a smartlead client into the email
 * account datastore.
 *
 * The inboxes are read from the smartlead api and pushed into the email
 * infrastructure service which hydrates the creation time and the warmup
 * reputation (the deliverability score) of every inbox.
 *
 * Usage:
 *   SMARTLEAD_REPORT_API_KEY=... API_KEY=... SMARTLEAD_CLIENT_ID=22 \
 *     node client/tools/importEmailAccounts.js
 */
const { fetch } = require('cross-fetch');

const API_URL = process.env.API_URL
  ? process.env.API_URL
  : 'https://internal.prod.tenex.email';
const API_KEY = process.env.API_KEY;
const SMARTLEAD_API_KEY = process.env.SMARTLEAD_REPORT_API_KEY;
const SMARTLEAD_CLIENT_ID = process.env.SMARTLEAD_CLIENT_ID;
const TAGS = process.env.TAGS ? process.env.TAGS.split(',') : [];
const PAGE_SIZE = 100;

const getSmartleadInboxes = async () => {
  const inboxes = [];
  let offset = 0;
  // The smartlead api is offset/limit paginated.
  for (;;) {
    const url = `https://server.smartlead.ai/api/v1/email-accounts/?api_key=${SMARTLEAD_API_KEY}&offset=${offset}&limit=${PAGE_SIZE}`;
    const res = await fetch(url);
    if (!res.ok) {
      throw new Error(`Unable to list the smartlead inboxes: ${res.status}`);
    }
    const page = await res.json();
    if (!page || page.length === 0) {
      return inboxes;
    }
    inboxes.push(...page);
    if (page.length < PAGE_SIZE) {
      return inboxes;
    }
    offset += PAGE_SIZE;
  }
};

const importEmailAccounts = async () => {
  if (!API_KEY || !SMARTLEAD_API_KEY) {
    throw new Error('API_KEY and SMARTLEAD_REPORT_API_KEY are required');
  }
  const inboxes = await getSmartleadInboxes();
  const emailAccounts = inboxes
    .filter((inbox) =>
      SMARTLEAD_CLIENT_ID
        ? `${inbox.client_id}` === `${SMARTLEAD_CLIENT_ID}`
        : !!inbox.client_id,
    )
    .map((inbox) => ({
      smartleadInboxId: `${inbox.id}`,
      smartleadClientId: `${inbox.client_id}`,
      email: inbox.from_email,
      tags: TAGS,
    }));
  console.log(`Importing ${emailAccounts.length} email accounts`);
  const res = await fetch(`${API_URL}/emailinfra/email-account/import`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-API-KEY': API_KEY,
    },
    body: JSON.stringify(emailAccounts),
  });
  const body = await res.json();
  console.log(`Imported: ${body?.imported?.length}`);
  console.log(`Failed: ${JSON.stringify(body?.failed ? body.failed : [])}`);
};

importEmailAccounts().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

/**
 * Re-hydrates the deliverability score (the smartlead warmup reputation) of
 * every known sending inbox, or of a single inbox when SMARTLEAD_INBOX_ID is
 * provided.
 *
 * Usage:
 *   API_KEY=... node client/tools/syncEmailAccountReputation.js
 *   API_KEY=... SMARTLEAD_INBOX_ID=101 node client/tools/syncEmailAccountReputation.js
 */
const { fetch } = require('cross-fetch');

const API_URL = process.env.API_URL
  ? process.env.API_URL
  : 'https://internal.prod.tenex.email';
const API_KEY = process.env.API_KEY;
const SMARTLEAD_INBOX_ID = process.env.SMARTLEAD_INBOX_ID;

const syncReputation = async () => {
  if (!API_KEY) {
    throw new Error('API_KEY is required');
  }
  const url = SMARTLEAD_INBOX_ID
    ? `${API_URL}/emailinfra/email-account/${SMARTLEAD_INBOX_ID}/sync`
    : `${API_URL}/emailinfra/email-account/sync`;
  console.log(`Syncing the deliverability scores: ${url}`);
  const res = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-API-KEY': API_KEY,
    },
  });
  if (!res.ok) {
    throw new Error(`Unable to sync the deliverability scores: ${res.status}`);
  }
  const body = await res.json();
  if (SMARTLEAD_INBOX_ID) {
    console.log(
      `${body?.email}: ${body?.deliverabilityScore} (${body?.deliverabilityScoreBand})`,
    );
    return;
  }
  (body?.synced ? body.synced : []).forEach((emailAccount) => {
    console.log(
      `${emailAccount?.email}: ${emailAccount?.deliverabilityScore} (${emailAccount?.deliverabilityScoreBand})`,
    );
  });
  console.log(`Failed: ${JSON.stringify(body?.failed ? body.failed : [])}`);
};

syncReputation().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

