/**
 * The shape accepted by the service when an email account is handed over from
 * a caller (a script, another service, the smartlead api, ...). It is looser
 * than {@link EmailAccountDto} which is what the http layer validates: ids may
 * still be numeric and any extra inbox metadata is simply carried along.
 */
export type EmailAccountInput = {
  smartleadInboxId: string | number;
  email?: string;
  smartleadClientId?: string | number;
  domain?: string;
  tags?: string[];
  campaignIds?: string[];
  deliverabilityScore?: number;
  createdAt?: string;
  updatedAt?: string;
} & Record<string, any>;

/** A lookup only needs the inbox id (or the email address) of an account. */
export type EmailAccountLookup = Partial<EmailAccountInput> | string | number;

export type EmailAccountListInput = EmailAccountListDto & Record<string, any>;

export type EmailAccountPaginationInput = Partial<EmailAccountPaginationDto> &
  Record<string, any>;

